package com.ecole.gestion_scolaire.registration.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime; import java.util.Map; @RestControllerAdvice(basePackages="com.ecole.gestion_scolaire.registration") public class RegistrationExceptionHandler{@ExceptionHandler({RegistrationNotFoundException.class}) @ResponseStatus(HttpStatus.NOT_FOUND) public Map<String,Object> notFound(RuntimeException e){return body(e);}@ExceptionHandler({InvalidRegistrationTransitionException.class,RegistrationValidationException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) public Map<String,Object> bad(RuntimeException e){return body(e);}private Map<String,Object> body(Exception e){return Map.of("timestamp",OffsetDateTime.now().toString(),"message",e.getMessage());}}
